 * The default region used when talking to the global STS endpoint.
 */
export const DEFAULT_STS_REGION = 'us-east-1';

/**
 * Builds a credential provider which assumes a customer owned (cross account) role.
 * The provider is lazy, credentials are only fetched when the provider is invoked
 * or when a client which was configured with it makes a call.
 */
export const getCustomerRoleCredentials = ({
    iamRoleArn,
    externalId,
    roleSessionName = 'meteringco-role-verification',
    region = DEFAULT_STS_REGION,
}: {
    iamRoleArn: string;
    externalId?: string;
    roleSessionName?: string;
    region?: string;
}): AwsCredentialIdentityProvider =>
    fromTemporaryCredentials({
        params: {
            RoleArn: iamRoleArn,
            ExternalId: externalId ? externalId : undefined,
            RoleSessionName: roleSessionName,
        },
        clientConfig: { region },
    });

/**
 * Proves that a customer owned role can actually be assumed with the supplied external id.
 * Resolves with a credential provider holding the temporary credentials, rejects with the
 * underlying STS error when the role cannot be assumed.
 */
export const assumeCustomerRole = async ({
    iamRoleArn,
    externalId,
    roleSessionName,
    region,
}: {
    iamRoleArn: string;
    externalId?: string;
    roleSessionName?: string;
    region?: string;
}): Promise<AwsCredentialIdentityProvider> => {
    const credentials = getCustomerRoleCredentials({ iamRoleArn, externalId, roleSessionName, region });
    // Invoking the provider performs the sts:AssumeRole call, this throws when the role,
    // its trust policy, or the external id are not usable by MeteringCo.
    await credentials();
    return credentials;
};
