import { BadRequestException } from '@nestjs/common';
import { Test, TestingModule } from '@nestjs/testing';
import { createMock } from '@golevelup/ts-jest';
import { CreateRoleCommand, IAMClient, PutRolePolicyCommand } from '@aws-sdk/client-iam';
import {
    CLOUD_IAM_ASSUME_ROLE_MESSAGE,
    CLOUD_IAM_INVENTORY_MESSAGE,
    CLOUD_IAM_MISSING_ROLE_MESSAGE,
    verifyCloudIAM,
} from './cloudIAMVerifier.js';
import { SettingsService } from './settings.service.js';
import { InfluxService } from '../influx/influx.service.js';

const ACCOUNT = '600000000042';
const EXTERNAL_ID = 'verifier-spec-external-id';
const READABLE_ROLE = `arn:aws:iam::${ACCOUNT}:role/verifier-spec-readable`;
const NO_PERMISSION_ROLE = `arn:aws:iam::${ACCOUNT}:role/verifier-spec-no-permission`;

const trustPolicy = (externalId?: string) =>
    JSON.stringify({
        Version: '2012-10-17',
        Statement: [
            {
                Effect: 'Allow',
                Principal: { AWS: '*' },
                Action: 'sts:AssumeRole',
                ...(externalId ? { Condition: { StringEquals: { 'sts:ExternalId': externalId } } } : {}),
            },
        ],
    });

const createRole = async (iam: IAMClient, RoleName: string, externalId?: string, allowEc2 = false) => {
    try {
        await iam.send(new CreateRoleCommand({ RoleName, AssumeRolePolicyDocument: trustPolicy(externalId) }));
    } catch (e) {
        if (e.name !== 'EntityAlreadyExists') throw e;
    }
    if (allowEc2) {
        await iam.send(
            new PutRolePolicyCommand({
                RoleName,
                PolicyName: 'read-inventory',
                PolicyDocument: JSON.stringify({
                    Version: '2012-10-17',
                    Statement: [{ Effect: 'Allow', Action: ['ec2:Describe*'], Resource: '*' }],
                }),
            }),
        );
    }
};

describe('cloudIAM verification', () => {
    beforeAll(async () => {
        const iam = new IAMClient({ region: process.env.AWS_REGION || 'us-east-1' });
        await createRole(iam, 'verifier-spec-readable', EXTERNAL_ID, true);
        await createRole(iam, 'verifier-spec-no-permission', EXTERNAL_ID, false);
    });

    it('accepts a role which can be assumed with the external ID and can read the inventory', async () => {
        await expect(verifyCloudIAM({ iamRoleArn: READABLE_ROLE, externalId: EXTERNAL_ID })).resolves.toEqual({
            iamRoleArn: READABLE_ROLE,
            externalId: EXTERNAL_ID,
        });
    });

    it('rejects a role which cannot be assumed with the supplied external ID', async () => {
        await expect(verifyCloudIAM({ iamRoleArn: READABLE_ROLE, externalId: 'not-the-external-id' })).rejects.toEqual(
            new BadRequestException({
                statusCode: 400,
                message: [CLOUD_IAM_ASSUME_ROLE_MESSAGE],
                error: 'Bad Request',
            }),
        );
    });

    it('rejects a garbage role', async () => {
        await expect(
            verifyCloudIAM({ iamRoleArn: 'wow a fake role', externalId: EXTERNAL_ID }),
        ).rejects.toBeInstanceOf(BadRequestException);
    });

    it('rejects a role which can be assumed but cannot read the instance inventory', async () => {
        await expect(verifyCloudIAM({ iamRoleArn: NO_PERMISSION_ROLE, externalId: EXTERNAL_ID })).rejects.toEqual(
            new BadRequestException({
                statusCode: 400,
                message: [CLOUD_IAM_INVENTORY_MESSAGE],
                error: 'Bad Request',
            }),
        );
    });

    it('treats a blank role as a disconnect and clears the external ID', async () => {
        await expect(verifyCloudIAM({ iamRoleArn: '', externalId: 'some-old-external-id' })).resolves.toEqual({
            iamRoleArn: '',
            externalId: '',
        });
    });

    it('rejects a cloudIAM block which names no role', async () => {
        await expect(verifyCloudIAM({} as never)).rejects.toEqual(
            new BadRequestException({
                statusCode: 400,
                message: [CLOUD_IAM_MISSING_ROLE_MESSAGE],
                error: 'Bad Request',
            }),
        );
        await expect(verifyCloudIAM({ externalId: EXTERNAL_ID } as never)).rejects.toEqual(
            new BadRequestException({
                statusCode: 400,
                message: [CLOUD_IAM_MISSING_ROLE_MESSAGE],
                error: 'Bad Request',
            }),
        );
    });

    describe('SettingsService.update', () => {
        let service: SettingsService;
        let influxService: InfluxService;

        beforeEach(async () => {
            const module: TestingModule = await Test.createTestingModule({ providers: [SettingsService] })
                .useMocker(createMock)
                .compile();
            service = module.get(SettingsService);
            influxService = module.get(InfluxService);
            jest.spyOn(influxService, 'getLatestSettings').mockResolvedValue([]);
            jest.spyOn(influxService, 'loadPoints').mockResolvedValue();
        });

        afterEach(() => jest.clearAllMocks());

        it('writes nothing when the role cannot be assumed', async () => {
            await expect(
                service.update({
                    businessID: 'some-business',
                    cloudIAM: { iamRoleArn: READABLE_ROLE, externalId: 'nope' },
                }),
            ).rejects.toBeInstanceOf(BadRequestException);
            expect(influxService.loadPoints).not.toBeCalled();
        });

        it('writes nothing when the role cannot read the inventory', async () => {
            await expect(
                service.update({
                    businessID: 'some-business',
                    cloudIAM: { iamRoleArn: NO_PERMISSION_ROLE, externalId: EXTERNAL_ID },
                }),
            ).rejects.toBeInstanceOf(BadRequestException);
            expect(influxService.loadPoints).not.toBeCalled();
        });

        it('saves a verified role', async () => {
            const { data } = await service.update({
                businessID: 'some-business',
                cloudIAM: { iamRoleArn: READABLE_ROLE, externalId: EXTERNAL_ID },
            });
            expect(influxService.loadPoints).toBeCalledTimes(1);
            expect(data[0].cloudIAM).toEqual({ iamRoleArn: READABLE_ROLE, externalId: EXTERNAL_ID });
        });

        it('clears the external ID on disconnect', async () => {
            const { data } = await service.update({
                businessID: 'some-business',
                cloudIAM: { iamRoleArn: '', externalId: 'stale-external-id' },
            });
            expect(influxService.loadPoints).toBeCalledTimes(1);
            expect(data[0].cloudIAM).toEqual({ iamRoleArn: '', externalId: '' });
        });

        it('does not touch cloudIAM when it is not part of the save', async () => {
            const { data } = await service.update({ businessID: 'some-business', businessName: 'foo' });
            expect(influxService.loadPoints).toBeCalledTimes(1);
            expect(data[0].businessName).toEqual('foo');
        });
    });
});
