import { BadRequestException, Logger } from '@nestjs/common';
import { serializeError } from 'serialize-error';
import { assumeCustomerRole, DEFAULT_STS_REGION } from '../utils/aws/awsSts.js';
import { getInstanceWithFilters } from '../utils/aws/awsEc2.js';

const logger = new Logger('CloudIAMVerifier');

/**
 * The shape of the cloudIAM block sent in on a settings save.
 * Kept local so the verification can be used from the DTOs without a circular import.
 */
export interface CloudIAMInput {
    iamRoleArn?: string;
    externalId?: string;
}

/**
 * Message used when a cloudIAM block is sent without naming a role at all.
 * An absent (undefined) role is a malformed request, it is not a disconnect,
 * a disconnect is expressed with an explicitly blank role.
 */
export const CLOUD_IAM_MISSING_ROLE_MESSAGE =
    'cloudIAM: An IAM role ARN must be supplied, send an empty iamRoleArn to disconnect the IAM role';

/**
 * Message used when MeteringCo is unable to assume the supplied role with the supplied external id.
 */
export const CLOUD_IAM_ASSUME_ROLE_MESSAGE =
    'cloudIAM: Unable to assume the IAM role provided with the external ID supplied. Please double check the IAM role, its trust policy and the external ID';

/**
 * Message used when the role can be assumed but the credentials cannot read the instance inventory.
 */
export const CLOUD_IAM_INVENTORY_MESSAGE =
    'cloudIAM: The IAM role provided cannot read the EC2 instance inventory (ec2:DescribeInstances). Please double check the permissions attached to the IAM role';

const cloudIAMBadRequest = (message: string): BadRequestException =>
    new BadRequestException({ statusCode: 400, message: [message], error: 'Bad Request' });

/**
 * Returns true when the supplied role is an explicit request to disconnect the customer's role.
 */
export const isCloudIAMDisconnect = (iamRoleArn: unknown): boolean =>
    typeof iamRoleArn === 'string' && iamRoleArn.trim() === '';

/**
 * Verifies the customer supplied scraper role before anything is persisted.
 *
 * 1. The role must be assumable by MeteringCo with the supplied external id.
 * 2. The credentials returned by that assume role call must be able to read the
 *    instance inventory which the collection (scraping) jobs rely on.
 *
 * A failure of either check is a bad request, so nothing else in the save is written.
 * A blank role is a disconnect, it skips the checks and clears the external id.
 */
export const verifyCloudIAM = async (
    cloudIAM: CloudIAMInput,
    { region = process.env.AWS_REGION || DEFAULT_STS_REGION }: { region?: string } = {},
): Promise<{ iamRoleArn: string; externalId?: string }> => {
    if (!cloudIAM || typeof cloudIAM !== 'object' || Array.isArray(cloudIAM)) {
        throw cloudIAMBadRequest(CLOUD_IAM_MISSING_ROLE_MESSAGE);
    }

    const { iamRoleArn, externalId } = cloudIAM;

    if (isCloudIAMDisconnect(iamRoleArn)) {
        // Disconnecting the role, the external id is meaningless without a role so it is cleared.
        logger.log('Blank IAM role supplied, disconnecting the customer role and clearing the external ID');
        return { iamRoleArn: '', externalId: '' };
    }

    if (typeof iamRoleArn !== 'string') {
        // A cloudIAM block which does not name a role is invalid, it is not a disconnect.
        throw cloudIAMBadRequest(CLOUD_IAM_MISSING_ROLE_MESSAGE);
    }

    let credentials;
    try {
        credentials = await assumeCustomerRole({ iamRoleArn, externalId, region });
    } catch (error) {
        logger.error(
            `Unable to assume customer role ${iamRoleArn} with external ID ${externalId}: ${JSON.stringify(
                serializeError(error),
            )}`,
        );
        throw cloudIAMBadRequest(CLOUD_IAM_ASSUME_ROLE_MESSAGE);
    }

    try {
        // The same inventory read the collection jobs perform, proving the credentials are usable.
        await getInstanceWithFilters(region, credentials, []);
    } catch (error) {
        logger.error(
            `Assumed role ${iamRoleArn} cannot read the instance inventory: ${JSON.stringify(serializeError(error))}`,
        );
        throw cloudIAMBadRequest(CLOUD_IAM_INVENTORY_MESSAGE);
    }

    return externalId === undefined || externalId === null ? { iamRoleArn } : { iamRoleArn, externalId };
};
"
}

